INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.74.0',
  '2026-08-06',
  'Поездки Яндекс Go из почты становятся тратами',
  E'Отчёты о поездке от Яндекс Go теперь разбираются так же, как чеки магазинов. Пересылаете письмо на заведённый адрес — и поездка сама становится тратой: сумма, дата и время подачи, счёт списания.\n\nСписка товаров у поездки нет, и делить её по группам нечего. Вместо этого в заметку к трате уезжает всё, ради чего отчёт вообще открывают: маршрут с временем подачи и высадки, машина с номером и цветом, тариф, время и расстояние в пути, перевозчик и водитель. Через полгода видно не «1600 драм», а откуда и куда ехали.\n\nСчёт списания берётся из самого письма. «•••• 6307» ищется по названиям ваших счетов, «Наличные» — по счёту типа «наличные»; не нашлось — берётся счёт, выбранный у адреса. Это же теперь работает и для чеков магазинов.\n\nПовторная пересылка того же отчёта трату не удвоит, а письма, пришедшие до настройки, разбираются кнопкой «Разобрать как чек» прямо в письме.',
  E'internal/receipts/yandexgo.go. Разбор идёт по «сжатому» списку строк текстовой части: пустые строки, [image: …] и голые ссылки выброшены — письмо свёрстано таблицей, и число пустых строк между подписью и значением от письма к письму гуляет, а без них подпись и значение всегда соседи. Заголовки разделов (Маршрут/Оплата/Детали/Перевозчик) переключают режим, значения переменной длины (адрес, марка машины) забираются до следующей известной подписи — иначе они съедали бы следующее поле.\n\nНомера заказа в отчёте нет, а защита от повторной пересылки нужна: order_no собирается из даты и времени подачи (20260806-1429) — две поездки не начинаются в одну минуту. Отсюда же external_id траты.\n\nПозиций у поездки нет намеренно. Раз позиций нет, Resplit оставляет трату без долей, и в отчёт она идёт своей категорией, а не куском «Не разобрано». Подробности переехали в новое поле mail_receipts.note (миграция 0097) и оттуда в finance_transactions.note; у чеков магазинов заметка по-прежнему собирается из номера заказа и числа позиций.\n\nБез итога ИЛИ без даты — ErrNotReceipt: трата без даты молча уехала бы на сегодня. Дата — «6 августа 2026 г.» своим разбором русских месяцев, при обрезанном теле берётся из темы. Валюта по знаку (֏/₽/₸/₾/$/€): Go работает в разных странах, и валюта в отчёте обозначена только знаком.\n\nreceiptimport.accountFor: последние 4 цифры карты ищутся подстрокой в названии и заметке счёта, «нал»/«cash» — по kind=cash. Отдельного поля «номер карты» ради одной подстроки не заводили. Не нашли — молча оставляем счёт по умолчанию: приписать трату не тому кошельку хуже, чем никакому.'
);
-- +goose StatementEnd

